package pqueue_test

import (
	"testing"

	"github.com/ai-verification/go-pqueue/internal/pqueue"
)

func TestPushPopOrder(t *testing.T) {
	pq := pqueue.New()
	pq.Push("low", 1)
	pq.Push("high", 10)
	pq.Push("med", 5)

	item, ok := pq.Pop()
	if !ok || item.Value != "high" || item.Priority != 10 {
		t.Fatalf("expected high/10, got %+v ok=%v", item, ok)
	}
	item, ok = pq.Pop()
	if !ok || item.Value != "med" || item.Priority != 5 {
		t.Fatalf("expected med/5, got %+v ok=%v", item, ok)
	}
	item, ok = pq.Pop()
	if !ok || item.Value != "low" || item.Priority != 1 {
		t.Fatalf("expected low/1, got %+v ok=%v", item, ok)
	}
}

func TestPopEmpty(t *testing.T) {
	pq := pqueue.New()
	_, ok := pq.Pop()
	if ok {
		t.Fatal("expected ok=false on empty queue")
	}
}

func TestPeekDoesNotConsume(t *testing.T) {
	pq := pqueue.New()
	pq.Push("only", 7)
	item, ok := pq.Peek()
	if !ok || item.Value != "only" {
		t.Fatalf("expected only/7, got %+v ok=%v", item, ok)
	}
	if pq.Len() != 1 {
		t.Fatalf("peek consumed item: Len=%d", pq.Len())
	}
}

func TestLenAndIsEmpty(t *testing.T) {
	pq := pqueue.New()
	if !pq.IsEmpty() {
		t.Fatal("expected empty")
	}
	pq.Push("a", 1)
	pq.Push("b", 2)
	if pq.Len() != 2 {
		t.Fatalf("expected Len=2, got %d", pq.Len())
	}
	if pq.IsEmpty() {
		t.Fatal("expected non-empty")
	}
}

func TestSamePriority(t *testing.T) {
	pq := pqueue.New()
	pq.Push("x", 5)
	pq.Push("y", 5)
	_, ok1 := pq.Pop()
	_, ok2 := pq.Pop()
	if !ok1 || !ok2 {
		t.Fatal("expected both pops to succeed")
	}
	if pq.Len() != 0 {
		t.Fatalf("expected empty after 2 pops, got %d", pq.Len())
	}
}
